{
  "story": "Merge sort divides the collection into single items, then repeatedly merges sorted pairs until the entire array is ordered.",
  "aha": {
    "stateId": "merge",
    "observation": "Sub-lists are combined in sorted order by comparing their front elements."
  },
  "layout": {
    "preset": "card",
    "width": 640
  },
  "parts": [
    {
      "id": "rail",
      "kind": "step-rail",
      "bind": {
        "active": "inputs.stepIndex",
        "items": "variant.states"
      }
    },
    {
      "id": "pic",
      "kind": "fixed-picture",
      "bind": {
        "active": "inputs.stepIndex",
        "regions": "variant.regions",
        "values": "variant.states"
      }
    },
    {
      "id": "callout",
      "kind": "active-callout",
      "bind": {
        "target": "state.calloutRegion",
        "text": "state.sentence",
        "values": "variant.states"
      }
    },
    {
      "id": "readout",
      "kind": "value-readout",
      "bind": {
        "values": "state.readouts"
      }
    }
  ],
  "controls": [
    {
      "id": "stepIndex",
      "kind": "index",
      "label": "Step",
      "options": ["Divide", "Split", "Compare", "Merge"]
    },
    {
      "id": "resetBtn",
      "kind": "reset",
      "label": "Reset",
      "options": []
    }
  ],
  "data": {
    "variants": [
      {
        "label": "Merge Sort",
        "regions": [
          {
            "id": "r1",
            "label": "Left Bucket",
            "values": ["3", "1"]
          },
          {
            "id": "r2",
            "label": "Right Bucket",
            "values": ["4", "2"]
          }
        ],
        "states": [
          {
            "id": "divide",
            "label": "Divide",
            "sentence": "The array is split into two halves.",
            "why": "Splitting isolates elements.",
            "active": ["r1", "r2"],
            "calloutRegion": "r1",
            "readouts": [
              {
                "id": "phase",
                "label": "Phase",
                "value": "Splitting"
              }
            ]
          },
          {
            "id": "split",
            "label": "Split",
            "sentence": "Single elements are treated as sorted lists.",
            "why": "Base case reached.",
            "active": ["r1"],
            "calloutRegion": "r1",
            "readouts": [
              {
                "id": "phase",
                "label": "Phase",
                "value": "Base Case"
              }
            ]
          },
          {
            "id": "compare",
            "label": "Compare",
            "sentence": "Front elements of each sub-list are compared.",
            "why": "Determine smaller value.",
            "active": ["r1", "r2"],
            "calloutRegion": "r2",
            "readouts": [
              {
                "id": "phase",
                "label": "Phase",
                "value": "Comparing"
              }
            ]
          },
          {
            "id": "merge",
            "label": "Merge",
            "sentence": "Elements are merged back into a sorted array.",
            "why": "Combines sorted runs.",
            "active": ["r1", "r2"],
            "calloutRegion": "r1",
            "readouts": [
              {
                "id": "phase",
                "label": "Phase",
                "value": "Sorted"
              }
            ]
          }
        ]
      }
    ]
  }
}
